namespace ClearSpace {
public sealed class IniDirective {public string Key,Value;public int Line;}
public sealed class Winapp2Entry {
 public string Name;public int Line;public List<IniDirective> Directives=new List<IniDirective>();
 public IEnumerable<IniDirective> Get(string key){return Directives.Where(d=>Regex.IsMatch(d.Key,"^"+Regex.Escape(key)+"[0-9]*$",RegexOptions.IgnoreCase));}
 public string First(string key){var d=Get(key).FirstOrDefault();return d==null?"":d.Value;}
}
public sealed class Winapp2Pack {
 public string Version="本地未标版本",Raw,Hash,Origin;public List<Winapp2Entry> Entries=new List<Winapp2Entry>();
 public int FileKeys{get{return Entries.Sum(e=>e.Get("FileKey").Count());}}
 public int RegistryKeys{get{return Entries.Sum(e=>e.Get("RegKey").Count());}}
}
public sealed class Winapp2FileKey {public string Path;public string[] Masks;public bool Recursive,RemoveSelf;public int Line;}
public static class Winapp2Parser {
 public static Winapp2Pack Parse(string raw){
  if(raw==null||Encoding.UTF8.GetByteCount(raw)>Winapp2Store.MaxBytes)throw new InvalidDataException("INI 规则包超过 5 MB");
  var pack=new Winapp2Pack{Raw=raw};using(var sha=SHA256.Create())pack.Hash=BitConverter.ToString(sha.ComputeHash(Encoding.UTF8.GetBytes(raw))).Replace("-","");
  var names=new HashSet<string>(StringComparer.OrdinalIgnoreCase);Winapp2Entry current=null;int line=0;
  using(var reader=new StringReader(raw)){string value;while((value=reader.ReadLine())!=null){if(++line>150000||value.Length>4096)throw new InvalidDataException("INI 行数或行长度超限");value=value.Trim().TrimStart('\uFEFF');if(value.Length==0)continue;
   if(value.StartsWith(";")||value.StartsWith("#")){var version=Regex.Match(value,"^;\\s*Version:\\s*([0-9.]{1,30})",RegexOptions.IgnoreCase);if(version.Success)pack.Version=version.Groups[1].Value;continue;}
   if(value.StartsWith("[")&&value.EndsWith("]")){string name=value.Substring(1,value.Length-2).Trim();if(name.Length==0||name.Length>200||!names.Add(name)||pack.Entries.Count>=10000)throw new InvalidDataException("INI 节名重复、无效或超限（第 "+line+" 行）");current=new Winapp2Entry{Name=name,Line=line};pack.Entries.Add(current);continue;}
   int equal=value.IndexOf('=');if(current==null||equal<1)throw new InvalidDataException("INI 格式无效（第 "+line+" 行）");string key=value.Substring(0,equal).Trim(),data=value.Substring(equal+1).Trim();if(!Regex.IsMatch(key,"^[A-Za-z][A-Za-z0-9]*$")||current.Directives.Count>=4096)throw new InvalidDataException("INI 指令无效或过多");
   // Preserve every directive, including repeated unnumbered keys and numbered keys.
   current.Directives.Add(new IniDirective{Key=key,Value=data,Line=line});
  }}
  if(pack.Entries.Count==0||pack.FileKeys+pack.RegistryKeys==0)throw new InvalidDataException("文件不包含有效的 Winapp2 清理条目");return pack;
 }
 public static Winapp2FileKey FileKey(IniDirective directive){string[] parts=directive.Value.Split('|');if(parts.Length<2||parts.Length>4)throw new InvalidDataException("FileKey 字段数量无效");var masks=parts[1].Split(';');if(masks.Length==0||masks.Length>64||masks.Any(m=>String.IsNullOrWhiteSpace(m)||m.Length>200||m.IndexOfAny(new[]{'\\','/',':','|','\0'})>=0))throw new InvalidDataException("文件模式无效");var key=new Winapp2FileKey{Path=parts[0].Trim(),Masks=masks.Select(m=>m.Trim()).ToArray(),Line=directive.Line};foreach(string flag in parts.Skip(2)){if(flag.Equals("RECURSE",StringComparison.OrdinalIgnoreCase))key.Recursive=true;else if(flag.Equals("REMOVESELF",StringComparison.OrdinalIgnoreCase)){key.Recursive=true;key.RemoveSelf=true;}else throw new InvalidDataException("不支持的 FileKey 标志");}return key;}
 public static string MaskRegex(IEnumerable<string> masks){return "^(?:"+String.Join("|",masks.Select(m=>m=="*.*"?".*":Regex.Escape(m).Replace("\\*",".*").Replace("\\?",".")))+")$";}
}
public sealed class Winapp2Environment {
 public Dictionary<string,string[]> Variables=new Dictionary<string,string[]>(StringComparer.OrdinalIgnoreCase);public string Drive;public string[] AllowedBases,DeniedBases;public Version OSVersion;
 public static Winapp2Environment Windows(){
  var c=new Winapp2Environment{Drive=RuleBook.TargetDrive,OSVersion=Environment.OSVersion.Version};Func<Environment.SpecialFolder,string> folder=Environment.GetFolderPath;
  c.Variables["AppData"]=new[]{folder(Environment.SpecialFolder.ApplicationData)};c.Variables["LocalAppData"]=new[]{folder(Environment.SpecialFolder.LocalApplicationData)};c.Variables["ProgramData"]=c.Variables["CommonAppData"]=new[]{folder(Environment.SpecialFolder.CommonApplicationData)};
  c.Variables["UserProfile"]=new[]{folder(Environment.SpecialFolder.UserProfile)};c.Variables["LocalLowAppData"]=new[]{Path.Combine(folder(Environment.SpecialFolder.UserProfile),"AppData","LocalLow")};
  c.Variables["ProgramFiles"]=new[]{folder(Environment.SpecialFolder.ProgramFiles),folder(Environment.SpecialFolder.ProgramFilesX86)}.Where(p=>!String.IsNullOrEmpty(p)).Distinct(StringComparer.OrdinalIgnoreCase).ToArray();c.Variables["CommonProgramFiles"]=new[]{folder(Environment.SpecialFolder.CommonProgramFiles),folder(Environment.SpecialFolder.CommonProgramFilesX86)}.Where(p=>!String.IsNullOrEmpty(p)).Distinct(StringComparer.OrdinalIgnoreCase).ToArray();
  c.Variables["WinDir"]=new[]{folder(Environment.SpecialFolder.Windows)};c.Variables["SystemDrive"]=new[]{Path.GetPathRoot(folder(Environment.SpecialFolder.Windows))};c.Variables["Temp"]=new[]{Path.GetTempPath().TrimEnd('\\')};c.Variables["Public"]=new[]{Path.Combine(Path.GetPathRoot(folder(Environment.SpecialFolder.UserProfile)),"Users","Public")};c.Variables["Documents"]=new[]{folder(Environment.SpecialFolder.MyDocuments)};
  c.AllowedBases=c.Variables["AppData"].Concat(c.Variables["LocalAppData"]).Concat(c.Variables["ProgramData"]).Concat(c.Variables["LocalLowAppData"]).Concat(c.Variables["ProgramFiles"]).Concat(c.Variables["CommonProgramFiles"]).Concat(c.Variables["Temp"]).Concat(new[]{Path.Combine(c.Drive,"Temp"),Path.Combine(c.Drive,"Tmp"),Path.Combine(folder(Environment.SpecialFolder.UserProfile),".cache")}).ToArray();
  string data=folder(Environment.SpecialFolder.CommonApplicationData);c.DeniedBases=new[]{folder(Environment.SpecialFolder.Windows),Path.Combine(data,"Microsoft","Windows"),Path.Combine(data,"Microsoft","Windows Defender"),Path.Combine(data,"Package Cache"),Path.Combine(data,"Microsoft","Crypto"),CleanerSettings.Root};return c;
 }
 public string[] Templates(string template){if(String.IsNullOrWhiteSpace(template)||template.Length>1024||template.IndexOfAny(new[]{'/','\0','|',':','<','>','"'})>=0||template.Split('\\').Any(p=>p==".."||p==".")||template.Contains("**"))throw new InvalidDataException("禁止绝对路径、越界或不受支持的路径表达式");var m=Regex.Match(template,"^%([^%]+)%(?:\\\\(.*))?$");string[] bases;if(!m.Success||!Variables.TryGetValue(m.Groups[1].Value,out bases)||m.Groups[2].Value.Contains("%"))throw new InvalidDataException("不支持的路径变量");string tail=m.Groups[2].Value.TrimEnd('\\');if(tail.Split('\\').Length>24)throw new InvalidDataException("路径层级过深");return bases.Where(p=>!String.IsNullOrWhiteSpace(p)).Select(p=>tail.Length==0?Path.GetFullPath(p):Path.Combine(Path.GetFullPath(p),tail)).Distinct(StringComparer.OrdinalIgnoreCase).ToArray();}
 public string[] Expand(string template,bool files,CancellationToken token){var found=new List<string>();foreach(string pattern in Templates(template)){string root=Path.GetPathRoot(pattern),tail=pattern.Substring(root.Length).TrimEnd('\\');var current=new List<string>{root};string[] parts=tail.Split('\\');for(int index=0;index<parts.Length;index++){var next=new List<string>();foreach(string parent in current){token.ThrowIfCancellationRequested();try{if(!Engine.SafeAncestors(Path.Combine(parent,"probe")))continue;if(parts[index].Contains("*")||parts[index].Contains("?")){foreach(var entry in new DirectoryInfo(parent).GetFileSystemInfos(parts[index]).Take(256)){if((entry.Attributes&FileAttributes.ReparsePoint)==0&&((entry.Attributes&FileAttributes.Directory)!=0||files&&index==parts.Length-1))next.Add(entry.FullName);if(next.Count>=256)break;}}else{string p=Path.Combine(parent,parts[index]);if(Directory.Exists(p)||files&&index==parts.Length-1&&File.Exists(p))next.Add(p);}}catch{}if(next.Count>=256)break;}current=next.Take(256).ToList();if(current.Count==0)break;}found.AddRange(current);if(found.Count>=256)break;}return found.Distinct(StringComparer.OrdinalIgnoreCase).Take(256).ToArray();}
 public bool Allowed(string path){try{string p=Engine.Normalize(path);return p.StartsWith(Drive,StringComparison.OrdinalIgnoreCase)&&AllowedBases.Any(r=>Inside(p,r))&&!DeniedBases.Any(r=>Inside(p,r))&&Engine.SafeAncestors(Path.Combine(p,"probe"));}catch{return false;}}
 public static bool Inside(string path,string root){string p=Engine.Normalize(path),r=Engine.Normalize(root);return p.Equals(r,StringComparison.OrdinalIgnoreCase)||p.StartsWith(r+"\\",StringComparison.OrdinalIgnoreCase);}
}
public sealed class Winapp2Exclusion {
 public Regex DirectoryPattern,FilePattern;public bool Recursive;
 public bool Matches(string path){string parent=Path.GetDirectoryName(path);return DirectoryPattern.IsMatch(parent)&&FilePattern.IsMatch(Path.GetFileName(path));}
 public static List<Winapp2Exclusion> Parse(Winapp2Entry entry,Winapp2Environment environment){var exclusions=new List<Winapp2Exclusion>();foreach(var directive in entry.Get("ExcludeKey")){string[] fields=directive.Value.Split('|');if(fields.Length<2||fields.Length>3)throw new InvalidDataException("排除指令格式无效");if(fields[0].Equals("REG",StringComparison.OrdinalIgnoreCase))continue;bool recursive=fields[0].Equals("PATH",StringComparison.OrdinalIgnoreCase);if(!recursive&&!fields[0].Equals("FILE",StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("未知排除类型");string[] masks=(fields.Length==3?fields[2]:"*").Split(';');if(masks.Any(m=>String.IsNullOrWhiteSpace(m)||m.IndexOfAny(new[]{'\\','/',':','|'})>=0))throw new InvalidDataException("排除模式无效");foreach(string pattern in environment.Templates(fields[1])){string expression=Regex.Escape(pattern.TrimEnd('\\')).Replace("\\*","[^\\\\]*").Replace("\\?","[^\\\\]");exclusions.Add(new Winapp2Exclusion{Recursive=recursive,DirectoryPattern=new Regex("^"+expression+(recursive?"(?:\\\\.*)?":"")+"$",RegexOptions.IgnoreCase,TimeSpan.FromMilliseconds(100)),FilePattern=new Regex(Winapp2Parser.MaskRegex(masks),RegexOptions.IgnoreCase,TimeSpan.FromMilliseconds(100))});}}return exclusions;}
}
public sealed class Winapp2Compatibility {
 public int Entries,FileKeys,Supported,Blocked,RegistryKeys;public List<string> Lines=new List<string>();
 public string Summary{get{return Entries+" 条定义 · 可适配 "+Supported+" 条普通文件指令 · 默认保留 "+Blocked+" 条文件 / "+RegistryKeys+" 条注册表指令";}}
}
public static class Winapp2Adapter {
 static readonly string[] SensitiveParts={"cookies","login data","password","passwords","sessions","session storage","local storage","indexeddb","bookmarks","preferences","secure preferences","accounts","settings","config","configuration","wallet","keychain","credentials","chats","messages","backups","savegames","saved games","history","web data","sync data"};
 static bool Sensitive(string path){return path.Split('\\').Any(p=>SensitiveParts.Any(s=>p.Equals(s,StringComparison.OrdinalIgnoreCase)||p.StartsWith(s+".",StringComparison.OrdinalIgnoreCase)||p.StartsWith(s+"-",StringComparison.OrdinalIgnoreCase)));}
 static bool SensitiveEntry(Winapp2Entry entry){return Regex.IsMatch(entry.Name,"password|usernames|cookies|autofill|bookmarks|browsing history|download history|browsing session|web storage|sync data|preferences|saved games|security & threat|backup|restore",RegexOptions.IgnoreCase);}
 static bool CachePart(string part){string name=part.Trim('*','?');return PathPolicy.CacheName(name)||new[]{"IconCache","WebCache","INetCache","CachedData","CachedFiles","Media Cache Files","ScriptCache","QtWebEngineCache"}.Contains(name,StringComparer.OrdinalIgnoreCase)||Regex.IsMatch(name,"(^|[ _-])(cache|caches|logs|logfiles|temp|tmp|crashdumps|crash reports)($|[ _-])",RegexOptions.IgnoreCase);}
 static bool DiagnosticMasks(Winapp2FileKey key){return key.Masks.All(m=>Regex.IsMatch(m,"^[^\\\\/:|]+\\.(log|tmp|cache|dmp|etl)(\\.(old|bak|[0-9]+)|\\*)?$",RegexOptions.IgnoreCase)||new[]{"LOG","LOG.old"}.Contains(m,StringComparer.OrdinalIgnoreCase));}
 static Rule ManualRule(Winapp2Entry entry,Winapp2FileKey key,Winapp2Environment environment,List<Winapp2Exclusion> exclusions,string id,string software,string cacheGroup,string part,string evidence,string[] owners,CancellationToken token){
  string reason=BlockingReason(entry,key,environment);if(exclusions==null||!(reason!=null&&(reason.StartsWith("账号、配置")||reason.StartsWith("非明确缓存"))))return null;
  // Unsupported directives, invalid exclusions and system/personal root paths stay blocked.
  foreach(var directive in entry.Directives)if(!Regex.IsMatch(directive.Key,"^(LangSecRef|Section|Default|Warning|DetectOS|SpecialDetect|DetectFile|Detect|FileKey|RegKey|ExcludeKey)[0-9]*$",RegexOptions.IgnoreCase))return null;
  environment.Templates(key.Path);foreach(var d in entry.Get("SpecialDetect"))SpecialNames(d.Value);foreach(var d in entry.Get("DetectOS"))OSMatches(d.Value,environment.OSVersion);
  string[] roots=environment.Expand(key.Path,false,token).Where(p=>environment.Allowed(p)&&!environment.AllowedBases.Any(b=>Engine.Normalize(p).Equals(Engine.Normalize(b),StringComparison.OrdinalIgnoreCase))&&key.Path.Split('\\').Length>=3).Take(64).ToArray();if(roots.Length==0)return null;
  return new Rule(id,entry.Name.TrimEnd(' ','*'),cacheGroup,"Winapp2 原本保留的文件范围，可在高级模式明确选择删除。原指令："+key.Path+"|"+String.Join(";",key.Masks),"风险删除可能移除账号、配置、历史、备份或软件数据，导致退出登录、记录丢失或软件异常。仅在核对路径后选择，强制先备份。",roots,0,false,owners){Protected=true,AllowManual=true,ManualIgnoresPersonalNames=true,ForceBackup=true,OnlyTop=!key.Recursive,FileNameRegex=Winapp2Parser.MaskRegex(key.Masks),ManualAdditionalExclude=p=>exclusions.Any(x=>x.Matches(p)),Software=software,Part=software+" · "+part+" · 原规则保留文件",GroupOverride="保留项目",Source=Winapp2Store.Url,Detection=evidence,Warning=entry.First("Warning")};
 }
 public static string BlockingReason(Winapp2Entry entry,Winapp2FileKey key,Winapp2Environment environment){
  if(SensitiveEntry(entry)||Sensitive(key.Path))return "账号、配置、历史、备份或个人资料范围，保留";
  foreach(var d in entry.Directives)if(!Regex.IsMatch(d.Key,"^(LangSecRef|Section|Default|Warning|DetectOS|SpecialDetect|DetectFile|Detect|FileKey|RegKey|ExcludeKey)[0-9]*$",RegexOptions.IgnoreCase))return "存在未支持指令 "+d.Key+"，保留整项";
  try{environment.Templates(key.Path);Winapp2Exclusion.Parse(entry,environment);foreach(var d in entry.Get("SpecialDetect"))SpecialNames(d.Value);foreach(var d in entry.Get("DetectOS"))OSMatches(d.Value,environment.OSVersion);}catch(Exception ex){return ex.Message;}
  var variable=Regex.Match(key.Path,"^%([^%]+)%").Groups[1].Value;
  if(new[]{"WinDir","Documents","Public"}.Contains(variable,StringComparer.OrdinalIgnoreCase))return "系统或个人资料目录，保留";
  if(variable.Equals("UserProfile",StringComparison.OrdinalIgnoreCase)&&!Regex.IsMatch(key.Path,"^%UserProfile%\\\\(AppData\\\\|\\.cache\\\\)",RegexOptions.IgnoreCase))return "用户个人目录，保留";
  if(variable.Equals("SystemDrive",StringComparison.OrdinalIgnoreCase)&&!Regex.IsMatch(key.Path,"^%SystemDrive%\\\\(Temp|Tmp)(\\\\|$)",RegexOptions.IgnoreCase))return "系统盘根目录范围，保留";
  bool cache=variable.Equals("Temp",StringComparison.OrdinalIgnoreCase)||key.Path.Split('\\').Skip(1).Any(CachePart);bool diagnostics=DiagnosticMasks(key);
  return cache||diagnostics?null:"非明确缓存目录且文件模式过宽，保留";
 }
 public static Winapp2Compatibility Analyze(Winapp2Pack pack,Winapp2Environment environment){var report=new Winapp2Compatibility{Entries=pack.Entries.Count,FileKeys=pack.FileKeys,RegistryKeys=pack.RegistryKeys};foreach(var entry in pack.Entries){foreach(var directive in entry.Get("FileKey")){string reason;try{reason=BlockingReason(entry,Winapp2Parser.FileKey(directive),environment);}catch(Exception ex){reason=ex.Message;}if(reason==null)report.Supported++;else report.Blocked++;report.Lines.Add((reason==null?"可适配普通候选":"默认保留")+" | "+entry.Name+" | 第 "+directive.Line+" 行 | "+directive.Key+"="+directive.Value+(reason==null?"":" | "+reason));}foreach(var directive in entry.Get("RegKey"))report.Lines.Add("保留 | "+entry.Name+" | "+directive.Key+"="+directive.Value+" | 社区任意注册表删除未接入执行器");}return report;}
 public static bool OSMatches(string value,Version actual){if(String.IsNullOrEmpty(value))return true;string[] range=value.Split('|');if(range.Length!=2)throw new InvalidDataException("DetectOS 必须是最低版本|最高版本");for(int i=0;i<2;i++){if(range[i].Length==0)continue;Version bound;if(!Version.TryParse(range[i],out bound))throw new InvalidDataException("DetectOS 版本无效");var comparable=bound.Build<0?new Version(actual.Major,actual.Minor):bound.Revision<0?new Version(actual.Major,actual.Minor,Math.Max(0,actual.Build)):actual;if(i==0&&comparable<bound||i==1&&comparable>bound)return false;}return true;}
 static bool RegistryDetected(string value){try{string[] parts=value.Split(new[]{'\\'},2);if(parts.Length!=2||parts[1].IndexOfAny(new[]{'*','?','|'})>=0)return false;RegistryHive hive;if(!new Dictionary<string,RegistryHive>(StringComparer.OrdinalIgnoreCase){{"HKCU",RegistryHive.CurrentUser},{"HKLM",RegistryHive.LocalMachine},{"HKCR",RegistryHive.ClassesRoot},{"HKU",RegistryHive.Users},{"HKCC",RegistryHive.CurrentConfig}}.TryGetValue(parts[0],out hive))return false;foreach(var view in Environment.Is64BitOperatingSystem?new[]{RegistryView.Registry64,RegistryView.Registry32}:new[]{RegistryView.Registry32})using(var root=RegistryKey.OpenBaseKey(hive,view))using(var key=root.OpenSubKey(parts[1],false))if(key!=null)return true;}catch{}return false;}
 static string[] SpecialNames(string code){switch(code.ToUpperInvariant()){case "DET_CHROME":return new[]{"chrome.exe"};case "DET_FIREFOX":return new[]{"firefox.exe"};case "DET_EDGE":return new[]{"msedge.exe"};case "DET_OPERA":return new[]{"opera.exe"};case "DET_THUNDERBIRD":return new[]{"thunderbird.exe"};case "DET_IE":return new[]{"iexplore.exe"};default:throw new InvalidDataException("未支持的 SpecialDetect："+code);}}
 public static bool Detected(Winapp2Entry entry,DiscoveryResult discovery,Winapp2Environment environment,CancellationToken token,out string evidence){evidence="";try{if(entry.Get("DetectOS").Any(d=>!OSMatches(d.Value,environment.OSVersion)))return false;var special=entry.Get("SpecialDetect").Select(d=>SpecialNames(d.Value)).ToArray();foreach(var d in entry.Get("Detect")){token.ThrowIfCancellationRequested();if(RegistryDetected(d.Value)){evidence="注册表存在："+d.Value;return true;}}foreach(var d in entry.Get("DetectFile")){token.ThrowIfCancellationRequested();string[] paths=environment.Expand(d.Value,true,token);if(paths.Length>0){evidence="检测路径存在："+paths[0];return true;}}if(special.Any(exes=>discovery.Applications.Any(a=>exes.Contains(Path.GetFileName(a.Executable),StringComparer.OrdinalIgnoreCase)))){evidence="已发现应用符合 SpecialDetect";return true;}}catch(OperationCanceledException){throw;}catch{}return false;}
 public static List<Rule> Resolve(Winapp2Pack pack,DiscoveryResult discovery,Winapp2Environment environment,CancellationToken token,Action<string> status){var rules=new List<Rule>();int checkedEntries=0;var browserNames=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase){{"3001","Internet Explorer"},{"3006","Microsoft Edge"},{"3026","Mozilla Firefox"},{"3027","Opera"},{"3029","Google Chrome"},{"3030","Thunderbird"},{"3033","Vivaldi"},{"3034","Brave"}};
  foreach(var entry in pack.Entries){token.ThrowIfCancellationRequested();if(status!=null&&++checkedEntries%200==0)status("匹配 Winapp2 · "+checkedEntries+" / "+pack.Entries.Count);string evidence;if(!Detected(entry,discovery,environment,token,out evidence))continue;string title=entry.Name.TrimEnd(' ','*'),software=title,part="社区缓存";string browser;if(browserNames.TryGetValue(entry.First("LangSecRef"),out browser)&&title.StartsWith(browser,StringComparison.OrdinalIgnoreCase)){software=browser;part=title.Substring(browser.Length).Trim();}else{var app=discovery.Applications.Where(a=>!String.IsNullOrWhiteSpace(a.Name)&&a.Name.Length>=4&&title.StartsWith(a.Name,StringComparison.OrdinalIgnoreCase)).OrderByDescending(a=>a.Name.Length).FirstOrDefault();if(app!=null){software=app.Name;part=title.Substring(software.Length).Trim();}else{var split=Regex.Match(title,"^(.+?)\\s+(Caches?|Cached Files|Logs?|Log Files|Temporary Files|Temp Files|Crash.*|Diagnostics|Telemetry)$",RegexOptions.IgnoreCase);if(split.Success){software=split.Groups[1].Value;part=split.Groups[2].Value;}}}if(part.Length==0)part="社区缓存";
   var owners=discovery.Applications.Where(a=>ApplicationDiscovery.Matches(a,new[]{software},null,null)).Select(a=>Path.GetFileNameWithoutExtension(a.Executable)).Where(n=>!String.IsNullOrEmpty(n)).Distinct(StringComparer.OrdinalIgnoreCase).ToArray();if(owners.Length==0){var suffix=software.Replace(" ","").ToLowerInvariant();owners=new[]{software=="Google Chrome"?"chrome":software=="Microsoft Edge"?"msedge":software=="Mozilla Firefox"?"firefox":software=="Thunderbird"?"thunderbird":suffix};}
   string cacheGroup=browserNames.ContainsKey(entry.First("LangSecRef"))||entry.First("Section").IndexOf("browser",StringComparison.OrdinalIgnoreCase)>=0?"网页缓存":"软件缓存";var blocked=new List<string>();List<Winapp2Exclusion> exclusions;try{exclusions=Winapp2Exclusion.Parse(entry,environment);}catch(Exception ex){blocked.Add(ex.Message);exclusions=null;}int added=0,index=0;
   foreach(var directive in entry.Get("FileKey")){token.ThrowIfCancellationRequested();index++;try{var key=Winapp2Parser.FileKey(directive);string reason=BlockingReason(entry,key,environment);if(reason!=null||exclusions==null){var manual=ManualRule(entry,key,environment,exclusions,"winapp2-manual-"+entry.Line+"-"+index,software,cacheGroup,part,evidence,owners,token);if(manual!=null){rules.Add(manual);added++;}else blocked.Add(reason??"排除指令不可确认");continue;}string[] roots=environment.Expand(key.Path,false,token).Where(p=>environment.Allowed(p)&&!Sensitive(p.Substring(Path.GetPathRoot(p).Length))&&(DiagnosticMasks(key)||p.Split('\\').Any(CachePart))).Take(64).ToArray();if(roots.Length==0)continue;
     var r=new Rule("library-winapp2-"+entry.Line+"-"+index,title,"软件缓存","Winapp2 社区规则："+directive.Key+"="+directive.Value,"默认不选；仅处理旧缓存/日志并强制先备份。保留账号、设置与数据库。"+(key.RemoveSelf?" REMOVESELF 仅适配为递归清空文件，保留目录。":"")+(String.IsNullOrEmpty(entry.First("Warning"))?"":" 原规则警告："+entry.First("Warning")),roots,14,false,owners){Software=software,Part=part+(entry.Get("FileKey").Count()>1?" · "+index:""),GroupOverride=cacheGroup,Source=Winapp2Store.Url,Detection=evidence+"\nWinapp2 "+pack.Version+" / "+pack.Origin+"（社区未签名）\n原节：["+entry.Name+"]，第 "+directive.Line+" 行",OnlyTop=!key.Recursive,FileNameRegex=Winapp2Parser.MaskRegex(key.Masks),ExcludedNames=PathPolicy.SensitiveNames,ForceBackup=true,HeaderGuard=true,AllowManual=true,ManualIgnoresPersonalNames=true,Warning=entry.First("Warning")};r.AdditionalExclude=p=>Sensitive(Path.GetFileName(p))||new[]{".bak",".backup",".sav",".save"}.Contains(Path.GetExtension(p),StringComparer.OrdinalIgnoreCase)||Regex.IsMatch(Path.GetFileName(p),"\\.(db|sqlite|sqlite3|ini|json|config)(-|\\.)",RegexOptions.IgnoreCase)||exclusions.Any(x=>x.Matches(p));r.ManualAdditionalExclude=p=>exclusions.Any(x=>x.Matches(p));rules.Add(r);added++;
    }catch(OperationCanceledException){throw;}catch(Exception ex){blocked.Add(ex.Message);}}
   if(blocked.Count>0||entry.Get("RegKey").Any()){string why=String.Join("；",blocked.Distinct().Take(3))+(entry.Get("RegKey").Any()?"；"+entry.Get("RegKey").Count()+" 条社区注册表指令保留，不执行":"");rules.Add(new Rule("winapp2-retained-"+entry.Line,title+" · 已保留",cacheGroup,"原规则中存在未接入或受保护内容。"+(added>0?"可支持的文件指令另列在软件/网页缓存。":""),why,new string[0],14,false){Protected=true,Notice=true,Software=software,Part=software+" · "+part+" · 保留范围",GroupOverride="保留项目",Source=Winapp2Store.Url,Detection=evidence+"\n原节：["+entry.Name+"]"});}
  }return rules;
 }
}
public sealed class Winapp2Store {
 public const string Url="https://raw.githubusercontent.com/MoscaDotTo/Winapp2/master/Winapp2.ini";public const int MaxBytes=5*1024*1024;static readonly object Gate=new object();public string DirectoryPath;
 public Winapp2Store(string directory=null){DirectoryPath=directory??Path.Combine(CleanerSettings.Root,"Winapp2");}
 public Winapp2Pack Current(){foreach(string name in new[]{"active.ini","previous.ini"})try{string file=Path.Combine(DirectoryPath,name);if(File.Exists(file)){if(new FileInfo(file).Length>MaxBytes)continue;var p=Winapp2Parser.Parse(File.ReadAllText(file));p.Origin="本地缓存（未签名）";return p;}}catch{}return BundledSnapshot(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"rules","Winapp2.ini"));}
 internal static Winapp2Pack BundledSnapshot(string path){
  if(!File.Exists(path))throw new IOException("随附 Winapp2 规则文件缺失，请重新解压或安装完整的软件包。");
  using(var stream=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.Read)){
   if(stream.Length>MaxBytes)throw new InvalidDataException("随附 Winapp2 规则文件校验失败，请重新解压或安装完整的软件包。");
   string hash;using(var sha=SHA256.Create())hash=BitConverter.ToString(sha.ComputeHash(stream)).Replace("-","").ToLowerInvariant();
   if(!String.Equals(hash,ReleaseVersion.Winapp2SHA256,StringComparison.Ordinal))throw new InvalidDataException("随附 Winapp2 规则文件校验失败，请重新解压或安装完整的软件包。");
   stream.Position=0;using(var reader=new StreamReader(stream,new UTF8Encoding(false,true),true)){var pack=Winapp2Parser.Parse(reader.ReadToEnd());pack.Origin="随程序内置快照";return pack;}
  }
 }
 public Winapp2Pack Import(string raw,bool downloaded=false){var p=Winapp2Parser.Parse(raw);lock(Gate){var current=Current();int oldVersion,newVersion;if(downloaded&&Int32.TryParse(current.Version,out oldVersion)&&Int32.TryParse(p.Version,out newVersion)&&newVersion<oldVersion)throw new InvalidDataException("社区版本较旧，保留当前库");if(p.Hash==current.Hash)return current;AtomicFile.Write(Path.Combine(DirectoryPath,"previous.ini"),current.Raw);AtomicFile.Write(Path.Combine(DirectoryPath,"active.ini"),raw);}p.Origin=downloaded?"官方仓库 HTTPS 下载（未签名）":"本地导入（未签名）";return p;}
 public Winapp2Pack Rollback(){lock(Gate){string previous=Path.Combine(DirectoryPath,"previous.ini");if(!File.Exists(previous))throw new IOException("暂无 Winapp2 上一版本");var p=Winapp2Parser.Parse(File.ReadAllText(previous));AtomicFile.Write(Path.Combine(DirectoryPath,"active.ini"),p.Raw);p.Origin="已回退本地缓存（未签名）";return p;}}
 public Winapp2Pack Update(CancellationToken token){ServicePointManager.SecurityProtocol|=SecurityProtocolType.Tls12;var request=(HttpWebRequest)WebRequest.Create(Url);request.AllowAutoRedirect=false;request.Timeout=request.ReadWriteTimeout=30000;request.UserAgent="Clarity/"+ReleaseVersion.Display+" Winapp2";using(token.Register(()=>request.Abort()))using(var response=(HttpWebResponse)request.GetResponse()){if(response.StatusCode!=HttpStatusCode.OK||response.ContentLength>MaxBytes)throw new IOException("Winapp2 下载响应无效");using(var source=response.GetResponseStream())using(var buffer=new MemoryStream()){byte[] chunk=new byte[16384];int count;while((count=source.Read(chunk,0,chunk.Length))>0){token.ThrowIfCancellationRequested();if(buffer.Length+count>MaxBytes)throw new InvalidDataException("Winapp2 文件过大");buffer.Write(chunk,0,count);}token.ThrowIfCancellationRequested();return Import(new UTF8Encoding(false,true).GetString(buffer.ToArray()),true);}}}
}
